var addr = env.get('NETATMO_ADDRESS');
var devices = msg.payload.body.devices;

// Initialize the new data format structure
var data = {
    sensor_id: "netatmo",
    timestamp: Date.now(), // Current timestamp in milliseconds (fallback)
    metering_point: "K0",
    values: {}
};

// Loop through all devices found
for (let i = 0; i < devices.length; i++) {
    if (devices[i]._id == addr){
        // Store device identifiers
        data.values["device_id"] = devices[i]._id;

        var indoor_data = devices[i].dashboard_data;
        data.values["device_reachable"] = devices[i].reachable;

        if (devices[i].reachable) {
            // Indoor sensor data with individual timestamps (ts_ prefix)
            data.values["ts_temperature_indoor"] = indoor_data.time_utc * 1000;
            data.values["temperature_indoor"] = indoor_data.Temperature;

            data.values["ts_humidity_indoor"] = indoor_data.time_utc * 1000;
            data.values["humidity_indoor"] = indoor_data.Humidity;

            data.values["ts_co2_indoor"] = indoor_data.time_utc * 1000;
            data.values["co2_indoor"] = indoor_data.CO2;

            data.values["ts_pressure"] = indoor_data.time_utc * 1000;
            data.values["pressure"] = indoor_data.Pressure;

            data.values["ts_noise_level"] = indoor_data.time_utc * 1000;
            data.values["noise_level"] = indoor_data.Noise;

            data.values["ts_pressure_absolute"] = indoor_data.time_utc * 1000;
            data.values["pressure_absolute"] = indoor_data.AbsolutePressure;

            // WiFi signal strength (no timestamp, always current)
            data.values["wifi_signal_strength"] = devices[i].wifi_status;

            // Outdoor modules data (from devices[i].modules[j])
            var modules = devices[i].modules;
            if (modules && modules.length > 0) {
                for (let j = 0; j < modules.length; j++) {
                    // Read data of the first module only (outdoor sensor)
                    if (j==0) {
                        data.values["outdoor_module_reachable"] = modules[j].reachable;
                        data.values["outdoor_module_id"] = modules[j]._id;

                        if (modules[j].reachable) { 
                            var outdoor_data = modules[j].dashboard_data;

                            // Outdoor sensor data with individual timestamps (ts_ prefix)
                            data.values["ts_temperature_outdoor"] = outdoor_data.time_utc * 1000;
                            data.values["temperature_outdoor"] = outdoor_data.Temperature;

                            data.values["ts_humidity_outdoor"] = outdoor_data.time_utc * 1000;
                            data.values["humidity_outdoor"] = outdoor_data.Humidity;

                            // Module status data (no timestamp, always current)
                            data.values["battery_level"] = modules[j].battery_percent;
                            data.values["rf_signal_strength"] = modules[j].rf_status;
                            data.values["battery_voltage"] = modules[j].battery_vp;

                            // Calculate temperature difference with timestamp (use most recent of the two)
                            data.values["ts_temperature_difference"] = Math.max(indoor_data.time_utc, outdoor_data.time_utc) * 1000;
                            data.values["temperature_difference"] = indoor_data.Temperature - outdoor_data.Temperature;
                        }
                    }
                    if (j>0){
                        data.values["warning"] = "Multiple outdoor modules detected";
                    }
                }
            }
        }
      }
    }

msg.payload = data;
return msg;

var modbus = msg.payload

var dc = {};

dc["voltage"] = modbus["PZEM017/VOLTAGE"];
dc["current"] = modbus["PZEM017/CURRENT"];
// Bitshift with a 0.1 multiplier
dc["power"] = modbus["PZEM017/POWER_HIGH"] * 6553.6 + modbus["PZEM017/POWER_LOW"];
// Bitshift with a 1 multiplier
dc["energy_counter"] = modbus["PZEM017/ENERGY_HIGH"] * 65536 + modbus["PZEM017/ENERGY_LOW"];

msg.payload = dc;
return msg;

// Extract the values object
let values = msg.payload.values;

// Check if the values object exists
if (!values) {
    node.warn("No 'values' object found in payload");
    return null;
}

// Helper function to determine trend
function getTrend(current, previous, threshold) {
    if (previous === undefined) return "stable"; // first value
    if (current - previous > threshold) return "up";
    if (previous - current > threshold) return "down";
    return "stable";
}

// Extract desired fields
let temperature_indoor = values.temperature_indoor;
let co2_indoor = values.co2_indoor;
let temperature_outdoor = values.temperature_outdoor;

// Compute trends based on last stored values
let tempIndoorPrev = flow.get("temperature_indoor");
let co2IndoorPrev = flow.get("co2_indoor");
let tempOutdoorPrev = flow.get("temperature_outdoor");

let temperature_indoor_trend = getTrend(temperature_indoor, tempIndoorPrev, 0.1);
let indoor_co2_trend = getTrend(co2_indoor, co2IndoorPrev, 5);
let temperature_outdoor_trend = getTrend(temperature_outdoor, tempOutdoorPrev, 0.1);

// Store current values in flow context
flow.set("temperature_indoor", temperature_indoor);
flow.set("temperature_indoor_trend", temperature_indoor_trend);

flow.set("co2_indoor", co2_indoor);
flow.set("indoor_co2_trend", indoor_co2_trend);

flow.set("temperature_outdoor", temperature_outdoor);
flow.set("temperature_outdoor_trend", temperature_outdoor_trend);

// Optionally store humidity as before
flow.set("humidity_indoor", values.humidity_indoor);
flow.set("humidity_outdoor", values.humidity_outdoor);

// Pass through the message
return msg;

// Check if there is at least one relay
if (msg.payload.relays && msg.payload.relays.length > 0) {
    // Read the "ison" state of the first relay
    let isOn = msg.payload.relays[0].ison;

    // Store in flow context variable
    flow.set("bayernluft_on", isOn);
}

// Pass the message through unchanged
return msg;

// Check if sensor object exists
if (msg.payload.sensor) {
    // Store motion state (true/false)
    let motionDetected = msg.payload.sensor.motion;
    flow.set("motion_bad", motionDetected);

    // If motion is detected, store current timestamp
    if (motionDetected === true) {
        let currentTimestamp = msg.payload.sensor.timestamp || Math.floor(Date.now() / 1000);
        flow.set("last_motion_bad", currentTimestamp);
    }
}

// Check if lux object exists
if (msg.payload.lux) {
    // Store numeric lux value
    let luxValue = msg.payload.lux.value;
    flow.set("lux_bad", luxValue);
}

// Pass the message through unchanged
return msg;

// Check if sensor object exists
if (msg.payload.sensor) {
    // Store motion state (true/false)
    let motionDetected = msg.payload.sensor.motion;
    flow.set("motion", motionDetected);

    // If motion is detected, store current timestamp
    if (motionDetected === true) {
        let currentTimestamp = msg.payload.sensor.timestamp || Math.floor(Date.now() / 1000);
        flow.set("last_motion", currentTimestamp);
    }
}

// Check if lux object exists
if (msg.payload.lux) {
    // Store numeric lux value
    let luxValue = msg.payload.lux.value;
    flow.set("lux", luxValue);
}

// Pass the message through unchanged
return msg;

// --- Extract current CO2 and trend ---
let values = msg.payload.values;
if (!values || values.co2_indoor === undefined) {
    node.warn("No CO2 data found");
    return {};
}

let co2 = values.co2_indoor;

// Retrieve trend from flow context (must be stored previously)
let co2Trend = flow.get("indoor_co2_trend") || "stable";

// Retrieve current ventilator state
let ventilatorOn = flow.get("bayernluft_on");
if (ventilatorOn === undefined) ventilatorOn = false;

// --- Decision logic ---
let output = {};

// Always turn ON above 800ppm
if (co2 > 600 && !ventilatorOn) {
    output.on = true;
}
// Always turn OFF below 600ppm
else if (co2 < 600 && ventilatorOn) {
    output.on = false;
}
// Above 700ppm, turn ON if trend is rising
else if (co2 > 700 && co2Trend === "up" && !ventilatorOn) {
    output.on = true;
}

msg.payload = output;

// If no action required, output stays empty
return msg;

// Get current motion and last motion timestamp
let motionDetected = flow.get("motion_bad");
let lastMotion = flow.get("last_motion_bad");

// Current time in seconds
let now = Math.floor(Date.now() / 1000);

// If we have no motion timestamp yet, do nothing
if (!lastMotion) {
    msg.payload = {};
    return msg;
}

// Time since last motion in seconds
let secondsSinceMotion = now - lastMotion;

// Define thresholds
const FIVE_MIN = 5 * 60;
const FOUR_HOURS = 4 * 60 * 60;

// Retrieve current ventilator state
let ventilatorOn = flow.get("wc_on") || false;

// Default: no change
msg.payload = {};

// --- Logic ---
// Ventilator ON if: motion happened within 4h but not in last 5min
if (secondsSinceMotion < FOUR_HOURS && secondsSinceMotion > FIVE_MIN) {
    if (!ventilatorOn) {
        msg.payload = { on: true };
    }
}
// Ventilator OFF if: someone is in the bathroom right now
else if (motionDetected === true) {
    if (ventilatorOn) {
        msg.payload = { on: false };
    }
}
// Ventilator OFF if: no motion for more than 4h
else if (secondsSinceMotion >= FOUR_HOURS) {
    if (ventilatorOn) {
        msg.payload = { on: false };
    }
}

return msg;

// Check if there is at least one relay
if (msg.payload.relays && msg.payload.relays.length > 0) {
    // Read the "ison" state of the first relay
    let isOn = msg.payload.relays[0].ison;

    // Store in flow context variable
    flow.set("wc_on", isOn);
}

// Pass the message through unchanged
return msg;

// Ensure the payload has a "lights" array
if (msg.payload.lights && msg.payload.lights.length > 0) {
    let light = msg.payload.lights[0];

    // Extract relevant fields
    let isOn = light.ison;
    let brightness = light.brightness;
    let source = light.source;

    // Store in flow context (local variables)
    flow.set("kitchen_on", isOn);
    flow.set("kitchen_brightness", brightness);
    flow.set("kitchen_source", source);
}

// Pass the message through unchanged
return msg;

// Ensure the payload has a "lights" array
if (msg.payload.lights && msg.payload.lights.length > 0) {
    let light = msg.payload.lights[0];

    // Extract relevant fields
    let isOn = light.ison;
    let brightness = light.brightness;
    let source = light.source;

    // Store in flow context (local variables)
    flow.set("stairs_on", isOn);
    flow.set("stairs_brightness", brightness);
    flow.set("stairs_source", source);
}

// Pass the message through unchanged
return msg;

// Retrieve motion, timestamp, and lux from flow
let motion = flow.get("motion_living") || false;
let lastMotion = flow.get("last_motion_living") || 0;
let lux = flow.get("lux_living") || 0;

// Retrieve current dimmer state
let dimmerOn = flow.get("stairs_on") || false;
let dimmerBrightness = flow.get("stairs_brightness") || 0;
let dimmerSource = flow.get("stairs_source") || "unknown";

// Calculate time since last motion
let now = Math.floor(Date.now() / 1000);
let sinceMotion = now - lastMotion;

// Define thresholds
const OFF_DELAY = 15 * 60; // 15 minutes
const MAX_BRIGHTNESS = 70;
const MIN_BRIGHTNESS = 20;

// --- Calculate desired brightness based on lux ---
let desiredBrightness;

if (lux < 100) {
    desiredBrightness = 20;
} else if (lux < 150) {
    desiredBrightness = 30;
} else {
    // Linear scaling between 150 and 1000 lux
    let minLux = 150;
    let maxLux = 1000;
    let ratio = (lux - minLux) / (maxLux - minLux);
    desiredBrightness = 30 + ratio * (MAX_BRIGHTNESS - 30);
}

// Clamp value between MIN and MAX
desiredBrightness = Math.max(MIN_BRIGHTNESS, Math.min(MAX_BRIGHTNESS, desiredBrightness));
desiredBrightness = Math.round(desiredBrightness);

// Default: no change
msg.payload = {};

// --- LOGIC ---

// 1️⃣ Motion detected → ensure light is on and correct brightness
if (motion === true) {
    if ((!dimmerOn || dimmerBrightness !== desiredBrightness) && dimmerSource !== "input") {
        msg.payload = { on: true, brightness: desiredBrightness };
    }
}

// 2️⃣ No motion for more than 15 min → turn off
else if (sinceMotion > OFF_DELAY) {
    if (dimmerOn && dimmerSource !== "input") {
        msg.payload = { on: false };
    }
}

// 3️⃣ Otherwise: no action
else {
    msg.payload = {};
}

return msg;

// Extract temperature data from payload
let values = msg.payload.values || {};
let tempIndoor = values.temperature_indoor;
let tempOutdoor = values.temperature_outdoor;

// Get motion info from flow context
let motion = flow.get("motion") || false;
let lastMotion = flow.get("last_motion") || 0;

// Get current heating state
let heatingOn = flow.get("heating_on") || false;

// Current time and inactivity duration
let now = Math.floor(Date.now() / 1000);
let sinceMotion = now - lastMotion;

// Thresholds
const FROST_TEMP = 12;          // °C
const COMFORT_TEMP = 21;        // °C
const NO_MOTION_LIMIT = 60 * 60; // 1 hour

// Default: no change
msg.payload = {};

// --- LOGIC ---

// 1️⃣ Frost prevention: Always heat if very cold inside
if (tempIndoor < FROST_TEMP) {
    if (!heatingOn) {
        msg.payload = { on: true };
        flow.set("heating_on", true);
    }
}

// 2️⃣ Otherwise only heat if it's colder outside than inside
else if (tempOutdoor < tempIndoor) {

    // Turn ON if motion detected and below comfort temperature
    if (motion && tempIndoor < COMFORT_TEMP) {
        if (!heatingOn) {
            msg.payload = { on: true };
            flow.set("heating_on", true);
        }
    }

    // Turn OFF if temperature high enough or no motion for > 1h
    else if (tempIndoor >= COMFORT_TEMP || sinceMotion > NO_MOTION_LIMIT) {
        if (heatingOn) {
            msg.payload = { on: false };
            flow.set("heating_on", false);
        }
    }
}

// 3️⃣ If it's warmer outside than inside → stop heating
else if (tempOutdoor >= tempIndoor) {
    if (heatingOn) {
        msg.payload = { on: false };
        flow.set("heating_on", false);
    }
}

// --- END ---
return msg;

// Check if there is at least one relay
if (msg.payload.relays && msg.payload.relays.length > 0) {
    // Read the "ison" state of the first relay
    let isOn = msg.payload.relays[0].ison;

    // Store in flow context variable
    flow.set("heating_on", isOn);
}

// Pass the message through unchanged
return msg;
